const fs = require('fs');
const email = $input.item.json.senderEmail;
const memoryPath = `/home/node/data/memory/${email}.json`;

let memory = {
  sender: email,
  subject_history: [],
  last_interaction: "No previous interactions.",
  reply_history: [],
  timestamp: ""
};

try {
  if (fs.existsSync(memoryPath)) {
    const content = fs.readFileSync(memoryPath, 'utf8');
    memory = JSON.parse(content);
  }
} catch (err) {
  console.error('Error reading memory file:', err);
}

return [{ json: { ...$input.item.json, memory } }];

const d = $input.item.json;
const memory = d.memory;

let context = `Sender: ${d.senderName} <${d.senderEmail}>\n`;
if (memory.subject_history && memory.subject_history.length > 0) {
  context += `Subject History:\n${memory.subject_history.map(s => `- ${s}`).join('\n')}\n`;
  context += `Last Interaction: ${memory.last_interaction}\n`;
  context += `Last Reply History:\n${memory.reply_history.map(r => `- ${r}`).join('\n')}\n`;
} else {
  context += `No previous conversation history found. This is a first-time contact.\n`;
}

return [{ json: { ...d, memoryContext: context } }];

const d = $input.item.json;
const prompt = `You are an advanced AI Email Approval Agent. Your task is to analyze the following email, look at the past interaction memory, and decide on the next actions.

## PAST MEMORY CONTEXT
${d.memoryContext}

## CURRENT EMAIL
From: ${d.senderName} <${d.senderEmail}>
Subject: ${d.subject}
Received: ${d.receivedDate}

Body:
${d.emailBody}

## INSTRUCTIONS
Classify this email into one of these categories:
1. "spam" - If the email is unsolicited commercial email, spam, phishing, newsletter, or automatic system notification.
2. "auto_reply" - If the email is a routine inquiry (e.g. greeting, confirmation, basic question, simple request) that can be replied to automatically without risk.
3. "approval" - If the email is a complex business proposal, job application, high-urgency issue, meeting schedule request, support issue, or requires human judgment.

You MUST return ONLY a valid JSON object. No markdown, no conversational text, no explanation.

JSON Format:
{
  "category": "spam|auto_reply|approval",
  "confidence": 95,
  "reply_required": true,
  "approval_required": true,
  "reply": "Draft a professional reply text here. Keep it empty for spam.",
  "urgency_score": 5,
  "urgency_reason": "Brief reason for urgency score (1-10)",
  "priority": "high|medium|low",
  "sentiment": "positive|neutral|negative",
  "summary": "One sentence summary of the email",
  "follow_up_suggestion": "Suggested next follow-up action"
}`;

const payload = {
  model: 'llama3.2',
  prompt: prompt,
  stream: false,
  options: {
    temperature: 0.2
  }
};

return [{ json: { ...d, ollamaPayload: JSON.stringify(payload) } }];

const d = $('Build Ollama Payload').item.json;
const ollamaResponse = $input.item.json;

let ai = {};
try {
  const raw = ollamaResponse.response || '';
  const match = raw.match(/{[\s\S]*}/);
  if (match) {
    ai = JSON.parse(match[0]);
  } else {
    throw new Error('No JSON object found in Ollama response');
  }
} catch (e) {
  console.error('Failed to parse AI response:', e.message);
  ai = {
    category: "approval",
    confidence: 50,
    reply_required: true,
    approval_required: true,
    reply: `Dear ${d.senderName},\n\nThank you for reaching out. We have received your email regarding "${d.subject}" and will review it shortly.\n\nBest regards,\nNikhil`,
    urgency_score: 5,
    urgency_reason: "Ollama parse failure, defaulting to human review",
    priority: "medium",
    sentiment: "neutral",
    summary: "Ollama parsing failed, fallback manual review triggered",
    follow_up_suggestion: "Manual validation of AI parser logs"
  };
}

return [{
  json: {
    ...d,
    ai: {
      category: ai.category || 'approval',
      confidence: ai.confidence || 50,
      reply_required: ai.reply_required !== undefined ? ai.reply_required : true,
      approval_required: ai.approval_required !== undefined ? ai.approval_required : true,
      reply: ai.reply || '',
      urgency_score: ai.urgency_score || 5,
      urgency_reason: ai.urgency_reason || 'N/A',
      priority: ai.priority || 'medium',
      sentiment: ai.sentiment || 'neutral',
      summary: ai.summary || 'No summary generated.',
      follow_up_suggestion: ai.follow_up_suggestion || 'No follow-up action proposed.'
    }
  }
}];

const data = $input.item.json;
const now = new Date();
const dateStr = now.toISOString().replace('T', ' ').substring(0, 19);
const dateFile = now.toISOString().replace(/[:.]/g, '-').substring(0, 19);

const markdownLog = `# SPAM DETECTED — Email Ignored

**Date:** ${dateStr}  
**From:** ${data.senderName} <${data.senderEmail}>  
**Subject:** ${data.subject}  
**AI Category:** ${data.ai.category}  
**Confidence:** ${data.ai.confidence}%  
**Urgency:** ${data.ai.urgency_score}/10 (${data.ai.urgency_reason})  
**Priority:** ${data.ai.priority}  
**Sentiment:** ${data.ai.sentiment}  
**Summary:** ${data.ai.summary}  

---
## Email Body

\`\`\`
${data.emailBody}
\`\`\`

---
*AI Email Approval Agent — Spam Report*
`;

return [{
  json: {
    ...data,
    markdownLog,
    logFilePath: `/home/node/logs/spam/spam-${dateFile}.md` 
  }
}];

const fs = require('fs');
const path = require('path');
const data = $input.item.json;

try {
  const dir = path.dirname(data.logFilePath);
  if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); }
  fs.writeFileSync(data.logFilePath, data.markdownLog, 'utf8');
} catch (err) {
  console.error('Failed to save spam log:', err.message);
}

return [{ json: { ...data, spamLogSaved: true } }];

const fs = require('fs');
const path = require('path');
const data = $input.item.json;

const email = data.senderEmail;
const memoryPath = `/home/node/data/memory/${email}.json`;

let memory = data.memory;
memory.subject_history.push(data.subject);
memory.last_interaction = data.ai.summary;
memory.reply_history.push(data.ai.reply);
memory.timestamp = new Date().toISOString();

try {
  const dir = path.dirname(memoryPath);
  if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); }
  fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');
} catch (err) {
  console.error('Failed to save memory:', err.message);
}

return [{ json: { ...data, memorySaved: true, memory } }];

